string[] colors = {"red", "green", "blue"};
foreach (string color in colors)
{
    Console.WriteLine(color);
}

for (int i = 0; i < 5; i++)
{
    if (i == 2) continue;
    if (i == 4) break;
    Console.WriteLine(i);
}

for (int i = 0; i < 3; i++)
{
    for (int j = 0; j < 2; j++)
    {
        Console.Write(i + "," + j + " ");
    }
    Console.WriteLine();
}

for (int i = 0; i < 3; i++)
{
    Console.WriteLine(i);
}
